<script setup lang="ts">
import {computed,inject,ref,watch} from 'vue'
import {useWorkspace} from '../../workspace'
import {api,saveFile} from '../../api'
import {date,key} from '../../domain'
import {nodeDisplayName,nodeRegionLabel} from '../../nodePresentation'
import {attemptObservedAt} from '../../nodeQuality'
import {unlockGroups,unlockResult,unlockServiceAllowed,unlockServiceSkipReason} from '../../unlock'
import {homeModelKey} from './homeModel'
const w=useWorkspace(),m=inject(homeModelKey)!,selected=ref({service:'chatgpt_unlock',region:''}),exporting=ref(false)
const nodes=m.runNodes
watch(()=>JSON.stringify([nodes.value.map(key),w.hours.value,m.qualityCutoff.value]),()=>void m.readQualityNodes(nodes.value),{immediate:true})
const regions=computed(()=>[...new Set(nodes.value.map(n=>w.nodeUnlockRegion(n)))].sort())
const groups=computed(()=>unlockGroups.map(g=>({...g,items:g.ids.map(id=>m.displayServices.value.find(s=>s.service_id===id)).filter((s):s is NonNullable<typeof s>=>!!s)})).filter(g=>g.items.length))
watch([regions,groups],()=>{
 if(!regions.value.includes(selected.value.region))selected.value.region=regions.value[0]||''
 if(!groups.value.some(g=>g.items.some(s=>s.service_id===selected.value.service)))selected.value.service=groups.value[0]?.items[0]?.service_id||''
},{immediate:true})
function allowed(id:string,region:string){return unlockServiceAllowed(id,region,w.skipByApplicableRegions.value,w.settings.value?.unlock_service_regions)}
const entries=computed(()=>{
 const id=selected.value.service
 return nodes.value.filter(n=>w.nodeUnlockRegion(n)===selected.value.region).map(node=>{const attempt=m.shownService(node,id);return {node,attempt,result:unlockResult(attempt),at:attempt?attemptObservedAt(attempt):'',error:m.qualityErrors.value[key(node)]}}).sort((a,b)=>(Date.parse(b.at)||0)-(Date.parse(a.at)||0))
})
function cell(id:string,region:string){
 if(!allowed(id,region))return {label:'—',tone:'empty',title:unlockServiceSkipReason(id,region,w.skipByApplicableRegions.value,w.settings.value?.unlock_service_regions),available:0,total:0}
 const scope=nodes.value.filter(n=>w.nodeUnlockRegion(n)===region),results=scope.map(n=>unlockResult(m.shownService(n,id))),available=results.filter(r=>r.state==='available').length,total=results.filter(r=>r.state!=='unknown').length
 const error=scope.some(n=>m.qualityErrors.value[key(n)])
 return {label:total?`${available}/${total}`:error?'读取失败':'未测',tone:!total?'empty':available===total?'good':available?'warn':'bad',title:`${available} 可用 / ${total} 已测 · ${scope.length} 个节点`,available,total}
}
const current=computed(()=>cell(selected.value.service,selected.value.region)),service=computed(()=>m.displayServices.value.find(s=>s.service_id===selected.value.service)),latest=computed(()=>entries.value.find(e=>e.at)?.at)
const untested=computed(()=>entries.value.filter(e=>!e.attempt?.result&&!e.attempt?.started_at&&!e.error).map(e=>e.node))
const available=computed(()=>entries.value.filter(e=>e.result.state==='available').map(e=>e.node))
function detect(){if(!allowed(selected.value.service,selected.value.region))return;w.openPlan(untested.value);if(w.plan.value){w.plan.value.projects=['service'];w.plan.value.serviceIds=[selected.value.service];w.plan.value.includeReputation=false;w.plan.value.reputationServiceIds=[]}}
async function exportAvailable(){exporting.value=true;try{const result=await api.exportClash(available.value,service.value!.name+' · '+nodeRegionLabel(selected.value.region));if(await saveFile(result.yaml_content,'cst-unlock-available.yaml','application/x-yaml'))w.notify(`已导出 ${result.node_count} 个可用节点`)}catch(e){w.fail(e)}finally{exporting.value=false}}
</script>
<template><div class="unlock-matrix-layout">
 <section class="unlock-matrix-card"><p class="matrix-note">可用节点 / 已测节点 · 按真实落地分列<span v-if="m.qualityLoading.value"> · 正在读取记录…</span></p><div class="matrix-scroll"><table aria-label="按服务解锁矩阵"><thead><tr><th>服务</th><th v-for="region in regions" :key="region">{{nodeRegionLabel(region)}}</th></tr></thead><tbody v-for="g in groups" :key="g.id"><tr class="matrix-group"><th :colspan="regions.length+1">{{g.name}}</th></tr><tr v-for="s in g.items" :key="s.service_id"><th>{{s.name}}</th><td v-for="region in regions" :key="region"><button :aria-label="s.name+' · '+nodeRegionLabel(region)+' · '+cell(s.service_id,region).label" :aria-pressed="selected.service===s.service_id&&selected.region===region" :class="['matrix-cell',cell(s.service_id,region).tone]" :title="cell(s.service_id,region).title" @click="selected={service:s.service_id,region}">{{cell(s.service_id,region).label}}</button></td></tr></tbody></table></div><p v-if="!nodes.length||!groups.length" class="matrix-note">{{!nodes.length?'当前范围没有节点':'请先选择解锁项目'}}</p><div class="matrix-legend"><span class="good">全部可用</span><span class="warn">部分</span><span class="bad">都不可用</span><span>— 不适用 · 灰字未测</span></div></section>
 <aside class="matrix-inspector" aria-label="服务地区节点明细"><template v-if="service&&selected.region"><h2>{{service.name}} · {{nodeRegionLabel(selected.region)}}</h2><p class="matrix-note">{{current.label}}{{current.total?' 可用':''}} · 最近 {{latest?date(latest):'未测'}}</p><p v-if="!allowed(selected.service,selected.region)" class="matrix-note">{{current.title}}</p><template v-else><div class="matrix-node-list"><article v-for="e in entries" :key="key(e.node)"><header><strong>{{nodeDisplayName(e.node)}}</strong><span :class="e.result.tone">{{e.error?'读取失败':e.result.label}}</span></header><p v-if="e.error||e.result.reason">{{e.error||e.result.reason}}</p><time v-if="e.at">{{date(e.at)}}</time></article></div><div class="matrix-actions"><button class="hd-btn" :disabled="w.busy.value||m.qualityLoading.value||!untested.length" @click="detect">检测未测的 {{untested.length}} 个</button><button class="hd-btn" :disabled="exporting||!available.length" @click="exportAvailable">导出可用节点</button></div></template></template><p v-else class="matrix-note">点击一个格子查看节点。</p></aside>
</div></template>
<style scoped>
.unlock-matrix-layout{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:12px;align-items:start}.unlock-matrix-card,.matrix-inspector{background:var(--hd-card,#fff);border:1px solid var(--hd-line,#dedfe5);border-radius:12px;padding:16px;min-width:0}.matrix-note{font-size:12px;line-height:1.5;color:var(--hd-muted);margin:0 0 12px}.matrix-scroll{overflow:auto}.matrix-scroll table{width:100%;border-collapse:separate;border-spacing:5px;table-layout:fixed;min-width:460px}.matrix-scroll th{font-size:12px;text-align:left;font-weight:500;width:156px;overflow-wrap:anywhere}.matrix-scroll thead th:not(:first-child){text-align:center;width:auto;white-space:nowrap;color:var(--hd-muted)}.matrix-group th{font-weight:650;padding:10px 0 3px}.matrix-cell{border:2px solid transparent;border-radius:7px;width:100%;min-width:50px;padding:7px 3px;cursor:pointer;font-size:13px;font-variant-numeric:tabular-nums;white-space:nowrap}.matrix-cell.good{background:#d5ecd9;color:#17652b}.matrix-cell.warn{background:#f9dfa8;color:#80500c}.matrix-cell.bad{background:#f7d5d7;color:#a62932}.matrix-cell.empty{background:transparent;color:var(--hd-muted)}.matrix-cell[aria-pressed=true]{border-color:#79acfa;box-shadow:0 0 0 1px #79acfa}.matrix-legend{display:flex;gap:12px;flex-wrap:wrap;font-size:11px;color:var(--hd-muted);margin-top:12px}.matrix-legend span:not(:last-child):before{content:'';display:inline-block;width:8px;height:8px;border-radius:2px;background:currentColor;margin-right:5px}.good{color:#187c3b}.warn{color:#a56812}.bad{color:#bd333c}.empty{color:var(--hd-muted)}.matrix-inspector{position:sticky;top:12px}.matrix-inspector h2{font-size:15px;line-height:1.5;margin:0 0 5px;overflow-wrap:anywhere}.matrix-node-list{max-height:460px;overflow:auto}.matrix-node-list article{border-top:1px solid var(--hd-line);padding:12px 0}.matrix-node-list header{display:flex;justify-content:space-between;gap:10px;font-size:12px;line-height:1.5}.matrix-node-list strong{font-weight:500;flex:1}.matrix-node-list header span{max-width:48%;text-align:right}.matrix-node-list p{font-size:11px;line-height:1.5;color:var(--hd-muted);margin:5px 0;overflow-wrap:anywhere}.matrix-node-list time{font-size:10px;color:var(--hd-muted)}.matrix-actions{display:flex;gap:8px;flex-wrap:wrap;border-top:1px solid var(--hd-line);padding-top:12px}.matrix-actions button{flex:1;white-space:nowrap}@media(max-width:1100px){.unlock-matrix-layout{grid-template-columns:minmax(0,1fr) 290px}.unlock-matrix-card,.matrix-inspector{padding:12px}.matrix-actions button{font-size:11px}}@media(max-width:850px){.unlock-matrix-layout{grid-template-columns:1fr}.matrix-inspector{position:static}}
</style>
